contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call Put by sending Ether via fallback or directly using payable Put.
    // Parameters: amount to send and desired unlockTime value.
    function run(uint amount, uint unlockTime) public payable {
        require(address(this).balance >= amount);

        // read before-values via public getters
        // Acc is public mapping with auto-generated getter: Acc(address) returns (uint unlockTime, uint balance)
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        bool reverted;
        // call Put with value amount; must be top-level statement
        try c.Put{value: amount}(unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If call succeeded, balance in mapping must have increased by exactly amount
        // and contract balance must have increased by exactly amount.
        // If it reverted, nothing about balances is required by this assert (but we still assert reverted implies balances unchanged or may have changed due to reentrancy — to be safe we assert only the successful case)
        assert(reverted || (afterBalance == beforeBalance + amount && afterContractBal == beforeContractBal + amount));
    }

    // Receive to accept Ether when test contract is funded externally
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test Collect behaviour for this contract when msg.sender is this test contract.
    // Parameters:
    //  initialFund - how much wei to first deposit into c for this holder (via Put)
    //  sendWithPut - amount of wei forwarded when calling Put (must be <= initialFund and funds provided to this tx)
    //  collectAmt - amount to attempt to collect via Collect
    //  unlockTime - unlock timestamp argument supplied when depositing
    function run(uint initialFund, uint sendWithPut, uint collectAmt, uint unlockTime) public payable {
        // ensure the test contract has enough balance to fund the initial Put
        require(address(this).balance >= initialFund);
        // and ensure sendWithPut is not more than we promised to deposit (keeps relation between params)
        require(sendWithPut <= initialFund);

        // Fund this test contract's own balance by keeping msg.value (the harness will provide it).
        // First, make an initial Put to give this holder a positive Acc balance if sendWithPut>0
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Call Put to deposit sendWithPut into c for this test contract
        bool putReverted;
        try c.Put{value: sendWithPut}(unlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Read state after Put (or after failed Put)
        (uint midUnlock, uint midBalance) = c.Acc(address(this));
        uint midContractBal = address(c).balance;

        // Now try to Collect collectAmt
        bool collectReverted;
        try c.Collect{value: 0}(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read final state
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // Assertion: General invariant about Collect behaviour for this holder (this contract's address):
        // - If Collect did not revert, then the mapping balance must have decreased by exactly collectAmt
        //   and the contract's ETH balance must have decreased by exactly collectAmt as well.
        // - If Collect reverted, then mapping balance and contract balance did not both decrease by collectAmt.
        // This expresses that successful Collect transfers ETH out and updates the recorded balance accordingly.
        assert(
            (!collectReverted && midBalance >= collectAmt && afterBalance + collectAmt == midBalance && midContractBal >= collectAmt && afterContractBal + collectAmt == midContractBal)
            || (collectReverted && !(midBalance >= collectAmt && afterBalance + collectAmt == midBalance && midContractBal >= collectAmt && afterContractBal + collectAmt == midContractBal))
        );
    }

    receive() external payable {}
}

