        } catch {
            putReverted = true;
        }

        // read after-state
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If Put succeeded then recorded balance increased by at least sendWithPut
        // and contract balance increased by at least sendWithPut (both relative to before).
        // If Put reverted then both balances did not increase (remain <= before).
        assert(
            (!putReverted && afterBalance >= beforeBalance && afterBalance - beforeBalance >= sendWithPut && afterContractBal >= beforeContractBal && afterContractBal - beforeContractBal >= sendWithPut)
            || (putReverted && afterBalance <= beforeBalance && afterContractBal <= beforeContractBal)
        );
    }

    receive() external payable {}
