contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // preFund - amount to deposit into c via Put (so the test contract has recorded balance)
    // unlockOffset - if nonzero, will set unlockTime to block.timestamp + unlockOffset to allow Collect
    // collectAmt - amount to try to Collect
    function run(uint preFund, uint unlockOffset, uint collectAmt) public payable {
        // ensure this contract has funds to forward for Put
        require(address(this).balance >= preFund);

        // 1) Seed the contract by calling Put to ensure Acc[this] has at least preFund (if Put succeeds)
        bool putReverted;
        try c.Put{value: preFund}(unlockOffset > 0 ? block.timestamp + unlockOffset : 0) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // read before values
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // attempt Collect and record whether it reverted
        bool collectReverted;
        try c.Collect{value: 0}(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // read after values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If Collect did not revert and actually transferred funds, then recorded balance and contract balance both decreased by exactly collectAmt.
        // Otherwise (if it reverted OR preconditions didn't hold) neither recorded balance nor contract balance decreased.
        // We express "actually transferred funds" by checking that beforeBal >= collectAmt, beforeBal >= c.MinSum() and block.timestamp > beforeUnlock.
        uint minSum = c.MinSum();
        bool precondsHold = (beforeBal >= minSum) && (beforeBal >= collectAmt) && (block.timestamp > beforeUnlock);

        assert(
            // If Collect reverted: no decrease in recorded or contract balances
            (collectReverted && afterBal == beforeBal && afterContractBal == beforeContractBal)
            ||
            // If Collect succeeded: preconditions must have held and both balances decreased exactly by collectAmt
            (!collectReverted && precondsHold && beforeBal >= collectAmt && afterBal + collectAmt == beforeBal && afterContractBal + collectAmt == beforeContractBal)
        );
    }

    receive() external payable {}
}

