contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Params:
    // uint putAmount - wei to send to Put
    // uint unlockTime - unlock time for Put
    // uint collectAmount - amount to attempt to Collect
    function run(uint putAmount, uint unlockTime, uint collectAmount) public payable {
        // we must have funds in this test contract to send to c
        require(address(this).balance >= putAmount, "insufficient balance for put");

        // observe pre-state via public getters
        (uint preAccUnlock, uint preAccBalance) = c.Acc(address(this));
        uint preContractBal = address(c).balance;

        // perform Put as a plain top-level state-changing call
        c.Put{value: putAmount}(unlockTime);

        // observe mid-state
        (uint midAccUnlock, uint midAccBalance) = c.Acc(address(this));
        uint midContractBal = address(c).balance;

        // attempt Collect as a top-level call and record whether it reverted
        bool collectReverted;
        try c.Collect{value: 0}(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // observe post-state
        (uint postAccUnlock, uint postAccBalance) = c.Acc(address(this));
        uint postContractBal = address(c).balance;

        // Single assert: Put increased both balances by putAmount; Collect either reverted leaving balances unchanged,
        // or succeeded and decreased both balances by exactly collectAmount.
        assert(
            // Put effects:
            midAccBalance == preAccBalance + putAmount
            && midContractBal == preContractBal + putAmount
            // Collect effects:
            && (
                (collectReverted && postAccBalance == midAccBalance && postContractBal == midContractBal)
                || (!collectReverted && postAccBalance + collectAmount == midAccBalance && postContractBal + collectAmount == midContractBal)
            )
        );
    }

    // allow receiving Ether from successful Collect
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Params:
    // uint putAmount - wei to send to Put
    // uint unlockTime - unlock time for Put
    // uint collectAmount - amount to attempt to Collect
    function run(uint putAmount, uint unlockTime, uint collectAmount) public payable {
        // need funds to Put
        require(address(this).balance >= putAmount);

        // read pre-state
        (uint preUnlock, uint preBal) = c.Acc(address(this));
        uint preContractBal = address(c).balance;
        uint minSum = c.MinSum();

        // perform Put to ensure this test contract has recorded balance in c
        c.Put{value: putAmount}(unlockTime);

        // read mid-state after Put
        (uint midUnlock, uint midBal) = c.Acc(address(this));
        uint midContractBal = address(c).balance;

        // attempt Collect and record whether it reverted
        bool collectReverted;
        try c.Collect{value: 0}(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // read post-state
        (uint postUnlock, uint postBal) = c.Acc(address(this));
        uint postContractBal = address(c).balance;

        // If Collect succeeded, then preconditions must have held at time of call (balance >= MinSum, balance >= collectAmount, and now>unlock)
        // and the contract's external balance decreased by collectAmount (since ether sent out on success).
        // We express the rule using observable public getters and balances.
        assert(
            // Either Collect reverted, or if it didn't, then all required conditions were true and contract balance decreased by collectAmount
            (collectReverted)
            || (
                // midBal (caller balance before Collect) must be >= MinSum and >= collectAmount
                midBal >= minSum && midBal >= collectAmount
                // unlock time must have been strictly before the block.timestamp at call time. We observe that postUnlock equals midUnlock
                // because Put/Collect are the only state changes; Collect on success may change balance but not unlockTime for this holder.
                && midUnlock < block.timestamp
                // and the contract's external balance must have decreased by exactly collectAmount
                && postContractBal + collectAmount == midContractBal
                // and holder's recorded balance decreased by collectAmount
                && postBal + collectAmount == midBal
            )
        );
    }

    // allow receiving Ether from successful Collect
    receive() external payable {}
}
